def metrics(y, p):
    from sklearn.metrics import balanced_accuracy_score
    from sklearn.metrics import brier_score_loss
    from sklearn.metrics import recall_score
    from sklearn.metrics import roc_auc_score
    if np.unique(y).size < 2:
        return None
    return tuple(np.round([roc_auc_score(y, p), brier_score_loss(y, p), balanced_accuracy_score(y, p >= 0.5), *recall_score(y, p >= 0.5, average=None, labels=[0, 1], zero_division=0)], 3))

def score(y, p, c):
    from sklearn.metrics import brier_score_loss
    from sklearn.metrics import roc_auc_score
    return np.array([(roc_auc_score(y[c == i], p[c == i]), brier_score_loss(y[c == i], p[c == i])) for i in np.unique(c)])

def scores(y, p):
    from sklearn.metrics import brier_score_loss
    from sklearn.metrics import log_loss
    from sklearn.metrics import roc_auc_score
    return (roc_auc_score(y, p), brier_score_loss(y, p), log_loss(y, p, labels=[0, 1]))
